<?php $filters=$activityFilters??[];$relations=['owner','tenant','resident','family','representative','employee','domestic_staff','driver','security','maintenance','authorized','other'];?>
<div class="alert alert-primary d-flex gap-3"><i class="bi bi-shield-check fs-4"></i><div><strong>Actividad auditable de usuarios</strong><div>Primero filtra por apartamento/unidad. Luego puedes acotar por relación, correo, acción y presencia.</div></div></div>
<div class="card mb-3"><div class="card-body"><form method="get" class="row g-2 align-items-end"><input type="hidden" name="route" value="user-activity"><div class="col-lg-3"><label class="form-label">Apartamento / unidad</label><select name="property_id" class="form-select"><option value="">Todas</option><?php foreach($propertyOptions??[] as $p):?><option value="<?=$p['id']?>" <?=((int)($filters['property_id']??0)===(int)$p['id'])?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></div><div class="col-lg-2"><label class="form-label">Tipo / relación</label><select name="relationship_type" class="form-select"><option value="">Todos</option><?php foreach($relations as $r):?><option value="<?=e($r)?>" <?=($filters['relationship_type']??'')===$r?'selected':''?>><?=e(relationship_label($r))?></option><?php endforeach;?></select></div><div class="col-lg-1"><label class="form-label">Usuario</label><select class="form-select" name="user_type"><option value="">Todos</option><?php foreach(['resident'=>'Residente','admin'=>'Admin','security'=>'Seguridad','operator'=>'Operador'] as $uv=>$ul):?><option value="<?=e($uv)?>" <?=($filters['user_type']??'')===$uv?'selected':''?>><?=e($ul)?></option><?php endforeach;?></select></div><div class="col-lg-2"><label class="form-label">Correo</label><input class="form-control" name="email" value="<?=e($filters['email']??'')?>"></div><div class="col-lg-2"><label class="form-label">Acción</label><input class="form-control" name="action" value="<?=e($filters['action']??'')?>" placeholder="camera, login, reservation…"></div><div class="col-lg-1"><label class="form-label">Presencia</label><select class="form-select" name="online"><option value="">Todos</option><option value="online" <?=($filters['online']??'')==='online'?'selected':''?>>Online</option><option value="offline" <?=($filters['online']??'')==='offline'?'selected':''?>>Offline</option></select></div><div class="col-lg-2 d-grid"><button class="btn btn-primary"><i class="bi bi-funnel"></i> Filtrar</button></div></form></div></div>
<div class="row g-3 mb-3"><div class="col-xl-5"><div class="card h-100"><div class="card-header"><strong>Usuarios online / offline</strong><small class="d-block text-body-secondary">Online = señal de actividad recibida en los últimos 2 minutos.</small></div><div class="card-body p-0"><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>Usuario</th><th>Unidad</th><th>Estado</th><th>Última señal</th></tr></thead><tbody><?php foreach($onlineUsers??[] as $u):?><tr><td><strong><?=e($u['display_name']?:$u['email'])?></strong><small class="d-block"><?=e($u['email'])?></small></td><td><small><?=e($u['units']?:'—')?></small></td><td><span class="badge text-bg-<?=$u['presence']==='online'?'success':'secondary'?>"><?=$u['presence']==='online'?'Online':'Offline'?></span></td><td><small><?=e($u['last_seen_at']?:'Nunca')?></small></td></tr><?php endforeach;?><?php if(empty($onlineUsers)):?><tr><td colspan="4" class="text-center text-body-secondary py-3">Sin cuentas residentes.</td></tr><?php endif;?></tbody></table></div></div></div></div>
<div class="col-xl-7"><div class="card h-100"><div class="card-header"><strong>Correo de invitaciones</strong><small class="d-block text-body-secondary">Configura SMTP y prueba antes de invitar al primer residente.</small></div><div class="card-body"><form method="post" action="<?=url('mail-settings-save')?>" class="row g-2"><?=csrf_field()?><div class="col-md-3"><label class="form-label">Transporte</label><select class="form-select" name="transport"><option value="smtp" <?=($mailSettings['transport']??'smtp')==='smtp'?'selected':''?>>SMTP</option><option value="php_mail" <?=($mailSettings['transport']??'')==='php_mail'?'selected':''?>>PHP mail()</option></select></div><div class="col-md-5"><label class="form-label">Host SMTP</label><input class="form-control" name="smtp_host" value="<?=e($mailSettings['smtp_host']??'')?>"></div><div class="col-md-2"><label class="form-label">Puerto</label><input class="form-control" type="number" name="smtp_port" value="<?=e($mailSettings['smtp_port']??587)?>"></div><div class="col-md-2"><label class="form-label">Seguridad</label><select class="form-select" name="smtp_security"><option value="tls" <?=($mailSettings['smtp_security']??'tls')==='tls'?'selected':''?>>STARTTLS</option><option value="ssl" <?=($mailSettings['smtp_security']??'')==='ssl'?'selected':''?>>SSL/TLS</option><option value="none" <?=($mailSettings['smtp_security']??'')==='none'?'selected':''?>>Ninguna</option></select></div><div class="col-md-4"><label class="form-label">Usuario</label><input class="form-control" name="smtp_username" value="<?=e($mailSettings['smtp_username']??'')?>"></div><div class="col-md-4"><label class="form-label">Clave</label><input class="form-control" type="password" name="smtp_password" placeholder="<?=!empty($mailSettings['has_password'])?'Guardada · dejar vacía para conservar':'Clave SMTP'?>"></div><div class="col-md-4"><label class="form-label">Remitente</label><input class="form-control" type="email" name="from_email" value="<?=e($mailSettings['from_email']??'')?>"></div><div class="col-md-8"><label class="form-label">Nombre remitente</label><input class="form-control" name="from_name" value="<?=e($mailSettings['from_name']??'Property Hub')?>"></div><div class="col-md-4 d-flex align-items-end"><label class="form-check form-switch mb-2"><input class="form-check-input" type="checkbox" name="enabled" <?=!empty($mailSettings['enabled'])?'checked':''?>><span class="form-check-label">Correo habilitado</span></label></div><div class="col-12 text-end"><button class="btn btn-outline-primary"><i class="bi bi-save"></i> Guardar correo</button></div></form><hr><form method="post" action="<?=url('mail-test')?>" class="d-flex gap-2"><?=csrf_field()?><input class="form-control" type="email" name="test_email" required placeholder="correo donde recibir la prueba"><button class="btn btn-success text-nowrap"><i class="bi bi-send"></i> Enviar prueba</button></form></div></div></div></div>
<div class="card"><div class="card-header"><strong>Historial de actividad</strong><small class="d-block text-body-secondary">Máximo 500 eventos según los filtros actuales.</small></div><div class="card-body p-0"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Fecha</th><th>Persona</th><th>Apartamento / relación</th><th>Acción</th><th>Resultado</th><th>Origen</th></tr></thead><tbody><?php foreach($activity??[] as $a):?><tr><td class="text-nowrap"><small><?=e($a['created_at'])?></small></td><td><strong><?=e($a['display_name']?:'Sistema')?></strong><small class="d-block"><?=e($a['email']?:'')?></small></td><td><strong><?=e($a['property_name']?:'—')?></strong><small class="d-block text-body-secondary"><?=e(str_replace('||',' · ',$a['memberships']??''))?></small></td><td><code><?=e($a['action'])?></code><?php if($a['entity_type']):?><small class="d-block"><?=e($a['entity_type'])?><?=!empty($a['entity_id'])?' #'.e($a['entity_id']):''?></small><?php endif;?></td><td><span class="badge text-bg-<?=($a['result']==='success')?'success':(($a['result']==='denied')?'warning':'danger')?>"><?=e($a['result'])?></span><?php if($a['reason']):?><small class="d-block text-danger"><?=e($a['reason'])?></small><?php endif;?></td><td><small><?=e($a['ip_address']?:'')?></small></td></tr><?php endforeach;?><?php if(empty($activity)):?><tr><td colspan="6" class="text-center text-body-secondary py-4">No hay eventos para estos filtros.</td></tr><?php endif;?></tbody></table></div></div></div>
